draw((4,7)--(1,6));
draw((0,3)--(1,6));
draw((1,6)--(10,3));
draw((10,3)--(9,0));
draw((9,0)--(0,3));
draw((6,13/3)--(10,22/3));
draw((10,22/3)--(8,10));
draw((8,10)--(4,7));
draw((4,7)--(6,13/3));
